// limiter.go
package limiter

import (
	"errors"
	"sync"
	"time"
)

var ErrInvalidCapacity = errors.New("limiter: capacity must be positive")
var ErrInvalidRate = errors.New("limiter: rate must be positive")

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	capacity float64
	rate     float64 // tokens per second
	clock    Clock
}

// New creates a Limiter with the given burst capacity and refill rate
// (tokens per second). The bucket starts full.
func New(capacity, rate float64) (*Limiter, error) {
	return NewWithClock(capacity, rate, realClock{})
}

// NewWithClock is New with an injectable Clock.
func NewWithClock(capacity, rate float64, c Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, ErrInvalidCapacity
	}
	if rate <= 0 {
		return nil, ErrInvalidRate
	}
	if c == nil {
		c = realClock{}
	}
	now := c.Now()
	return &Limiter{
		tokens:   capacity,
		last:     now,
		capacity: capacity,
		rate:     rate,
		clock:    c,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

// AllowN reports whether n tokens are available, refilling the bucket
// based on elapsed time. It does not consume tokens if the request
// cannot be satisfied.
func (l *Limiter) AllowN(n float64) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}
	if l.tokens >= n {
		l.tokens -= n
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for tests/monitoring).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}
