package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	rate     float64   // tokens per second
	burst    int       // bucket capacity
	tokens   float64   // current tokens
	last     time.Time // last refill time
	clock    Clock
}

// New creates a Limiter with the given refill rate (tokens/sec) and burst
// capacity. The bucket starts full.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, realClock{})
}

// NewWithClock is New with an injectable clock.
func NewWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be positive")
	}
	return &Limiter{
		rate:   rate,
		burst:  burst,
		tokens: float64(burst),
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// advance refills tokens up to now. Caller must hold mu.
func (l *Limiter) advance(now time.Time) {
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens += elapsed * l.rate
		if l.tokens > float64(l.burst) {
			l.tokens = float64(l.burst)
		}
		l.last = now
	}
}

// AllowN reports whether n tokens may be consumed at time.Now.
func (l *Limiter) AllowN(n int) bool {
	return l.AllowNAt(n, l.clock.Now())
}

// AllowNAt reports whether n tokens may be consumed at the given time.
// It is safe for concurrent use.
func (l *Limiter) AllowNAt(n int, now time.Time) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for observability).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(l.clock.Now())
	return l.tokens
}
